use crate::dto::SymbolInterpretation;

pub fn interpret_life_path(number: u8) -> Option<SymbolInterpretation> {
    match number {
        1 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Life Path 1: The Independent Pioneer".to_string(),
            classical_grounding: "Pythagorean Tradition: 'The Monad (1) is the primal origin and sovereign impulse of all things; embodying self-determination, autonomy, and undaunted original will.'".to_string(),
            modern_translation: "First-mover founder, autonomous pioneer, and sovereign leader who charts uncharted territory and manifests vision through radical independence.".to_string(),
            shadow_and_caution: "Alienating isolationism, autocratic dismissal of collaborators, and stubborn unwillingness to negotiate.".to_string(),
            tactical_remedy: "Preserve sovereign autonomy while honoring domain expertise in co-founders; share equity and laurels generously upon achieving victory.".to_string(),
        }),
        2 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Life Path 2: The Diplomatic Peacemaker".to_string(),
            classical_grounding: "Pythagorean Tradition: 'The Dyad (2) is receptivity, connection, and balance; the principle of harmony, deep empathy, and synergistic communion.'".to_string(),
            modern_translation: "Master diplomat, strategic alliance architect, and psychological mediator who weaves win-win partnerships and calibrates interpersonal dynamics.".to_string(),
            shadow_and_caution: "Paralyzing indecision, morbid conflict avoidance, and dissolving personal agency to appease external demands.".to_string(),
            tactical_remedy: "Establish uncompromising non-negotiables and refusal criteria before brokering collaborative treaties.".to_string(),
        }),
        3 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Life Path 3: The Creative Communicator".to_string(),
            classical_grounding: "Pythagorean Tradition: 'The Triad (3) is the initial completion and synthetic triumph of form; representing expression, creative vitality, and artistic joy.'".to_string(),
            modern_translation: "Compelling storyteller, media innovator, and charismatic communicator who moves mass audiences and transmutes complex ideas into inspiring resonance.".to_string(),
            shadow_and_caution: "Scattered attention across too many projects, lack of follow-through, and substituting theatrical flash for substantive execution.".to_string(),
            tactical_remedy: "Enforce strict deadline discipline to concentrate creative bursts into finished, commercialized deliverables.".to_string(),
        }),
        4 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Life Path 4: The Master Builder & Foundation".to_string(),
            classical_grounding: "Pythagorean Tradition: 'The Tetrad (4) is the four cardinal elements and solid bedrock; governing law, order, justice, and enduring structure.'".to_string(),
            modern_translation: "Enterprise systems architect, Chief Operating Officer (COO), and bedrock operator who constructs unshakeable infrastructure for multi-decade prosperity.".to_string(),
            shadow_and_caution: "Bureaucratic rigidity, fear of necessary disruption, perfectionistic execution paralysis, and workaholism.".to_string(),
            tactical_remedy: "Preserve the robust operational framework while intentionally embedding a 20% innovation margin for experimental iteration.".to_string(),
        }),
        5 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Life Path 5: The Freedom Seeker & Catalyst".to_string(),
            classical_grounding: "Pythagorean Tradition: 'The Pentad (5) is kinetic dynamism, sensory expansion, and boundary-breaking exploration; the catalyst that shatters stagnant equilibrium.'".to_string(),
            modern_translation: "Global explorer, cutting-edge early adopter, and agile venture catalyst who orchestrates rapid pivots and thrives across fluid multi-disciplinary boundaries.".to_string(),
            shadow_and_caution: "Impulsive fickleness, breaking commitments, and generating a wake of half-finished initiatives due to craving novelty.".to_string(),
            tactical_remedy: "Enjoy freedom while anchoring your days to a non-negotiable core operational routine that keeps long-term projects on track.".to_string(),
        }),
        6 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Life Path 6: The Nurturing Guardian".to_string(),
            classical_grounding: "Pythagorean Tradition: 'The Hexad (6) is the first perfect number (1+2+3); the embodiment of cosmic balance, communal responsibility, and sacred protection.'".to_string(),
            modern_translation: "Ecosystem community builder, people-and-culture champion, and steadfast protector who establishes psychological safety and communal cohesion.".to_string(),
            shadow_and_caution: "Micromanaging intrusion, martyr complex, and burning out from carrying responsibilities that rightfully belong to others.".to_string(),
            tactical_remedy: "Empower others to solve their own challenges; establish firm personal boundaries so benevolence remains sustainable.".to_string(),
        }),
        7 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Life Path 7: The Truth Seeker & Mystic Analyst".to_string(),
            classical_grounding: "Pythagorean Tradition: 'The Heptad (7) is sacred contemplation and esoteric truth; the symbol of the mind investigating the fundamental laws of nature.'".to_string(),
            modern_translation: "Deep-tech researcher, data scientist, algorithmic philosopher, and investigative polymath who penetrates superficial illusions to master foundational truth.".to_string(),
            shadow_and_caution: "Intellectual cynicism, social detachment, and failing to communicate breakthrough discoveries due to perceived superiority.".to_string(),
            tactical_remedy: "Defend uninterrupted solitary thinking blocks, but package your derived insights with lucid clarity for the wider world.".to_string(),
        }),
        8 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Life Path 8: The Material & Executive Master".to_string(),
            classical_grounding: "Pythagorean Tradition: 'The Ogdoad (8) is the balance of eternity (∞), worldly power, karmic justice, and tangible manifestation.'".to_string(),
            modern_translation: "Chief Executive Officer (CEO), capital allocator, and infrastructure titan who marshals massive resources to engineer profound material influence and scalable prosperity.".to_string(),
            shadow_and_caution: "Obsession with material supremacy, treating collaborators merely as transactional instruments, and systemic overwork.".to_string(),
            tactical_remedy: "Wield capital and power as sacred stewardship to elevate civilization; maintain impeccable governance and ethical equilibrium.".to_string(),
        }),
        9 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Life Path 9: The Universal Humanitarian".to_string(),
            classical_grounding: "Pythagorean Tradition: 'The Ennead (9) is the terminus of numbers containing all previous wisdom; cosmic compassion, completion, and universal love.'".to_string(),
            modern_translation: "Global visionary, social impact innovator, and statesman who looks beyond private self-interest to steer humanity toward elevated consciousness.".to_string(),
            shadow_and_caution: "Impractical utopian daydreaming, brooding over bygone grievances, and self-sacrificing without structural ground.".to_string(),
            tactical_remedy: "Ground grand philosophical ideals into concrete, iterative daily deliverables; let go of obsolete historical baggage.".to_string(),
        }),
        11 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Master Life Path 11: The Intuitive Illuminator".to_string(),
            classical_grounding: "Master Number 11: 'Two pillars standing side-by-side to channel cosmic illumination; supreme intuitive revelation and high-frequency antenna.'".to_string(),
            modern_translation: "Epoch-defining visionary, paradigm illuminator, and intuitive transmitter who elevates collective awareness through revolutionary inspiration.".to_string(),
            shadow_and_caution: "Severe nervous system overload, paralyzing anxiety from intuitive dissonance, and sensory hypersensitivity.".to_string(),
            tactical_remedy: "Engage in daily somatic grounding (vigorous physical training and nature immersion) to protect and anchor high-voltage nervous circuitry.".to_string(),
        }),
        22 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Master Life Path 22: The Master Architect".to_string(),
            classical_grounding: "Master Number 22: 'Channels the spiritual intuition of the 11 into the physical bedrock of the 4; the master builder of civilizational monuments.'".to_string(),
            modern_translation: "Civilization architect, large-scale systems engineer, and global visionary who fuses profound idealism with unflinching, practical execution.".to_string(),
            shadow_and_caution: "Crushing paralysis from the weight of perceived destiny, and impossible perfectionist standards for collaborators.".to_string(),
            tactical_remedy: "Draft the 10-year master architectural blueprint, but rigorously atomize the very next step into an immediate, micro-deliverable.".to_string(),
        }),
        33 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Master Life Path 33: The Master Teacher & Healer".to_string(),
            classical_grounding: "Master Number 33: 'The vibration of unconditional compassion, spiritual stewardship, and the supreme teacher of universal wisdom.'".to_string(),
            modern_translation: "Transcendent spiritual mentor, cultural healer, and transformational leader guiding systemic collective evolution.".to_string(),
            shadow_and_caution: "Martyr complex seeking to carry all the suffering of the world single-handedly.".to_string(),
            tactical_remedy: "Heal, replenish, and love yourself first; pure selfless radiance can only beam from an overflowing internal fountain.".to_string(),
        }),
        _ => None,
    }
}

pub fn interpret_personal_year(year: u8) -> Option<SymbolInterpretation> {
    match year {
        1 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Personal Year 1: A New 9-Year Cycle Begins".to_string(),
            classical_grounding: "Epicycle Dynamics: 'Year 1 is planting the seed; dissolve obsolete legacies and initiate bold, uncompromised beginnings.'".to_string(),
            modern_translation: "Founding a new enterprise, charting a fresh career horizon, and taking sovereign initiatives towards radical independence.".to_string(),
            shadow_and_caution: "Hesitating due to nostalgia for the past, or demanding immediate harvest in the first year of sowing.".to_string(),
            tactical_remedy: "Seize sovereign initiative and officially inaugurate new ventures; seeds sown this year define the trajectory of the next 9 years.".to_string(),
        }),
        2 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Personal Year 2: Germination & Strategic Alliance".to_string(),
            classical_grounding: "Epicycle Dynamics: 'Year 2 is subterranean rooting; requiring patience, quiet collaboration, and diplomatic alignment.'".to_string(),
            modern_translation: "Deepening key partnerships, negotiating detailed agreements, and solidifying external strategic coalitions.".to_string(),
            shadow_and_caution: "Impatience when visible progress appears slow, or getting ensnared in interpersonal friction with partners.".to_string(),
            tactical_remedy: "Avoid unilateral force; prioritize deep listening and mutual trust to fortify your collaborative network.".to_string(),
        }),
        3 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Personal Year 3: Creative Expression & Public Expansion".to_string(),
            classical_grounding: "Epicycle Dynamics: 'Year 3 is budding and flowering; joy, creative expression, and dynamic visibility burst forth into the world.'".to_string(),
            modern_translation: "Outbound marketing, content publication, public networking, media exposure, and commanding widespread attention.".to_string(),
            shadow_and_caution: "Scattering energy across frivolous social distractions and failing to monetize increased attention.".to_string(),
            tactical_remedy: "Concentrate creative firepower into your single highest-leverage channel to permanently imprint your brand on the market.".to_string(),
        }),
        4 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Personal Year 4: Hard Work & Foundation Building".to_string(),
            classical_grounding: "Epicycle Dynamics: 'Year 4 strengthens the trunk against storms; diligence, infrastructure, and discipline are paramount.'".to_string(),
            modern_translation: "Process optimization, financial hardening, operational capability scaling, and establishing airtight standards.".to_string(),
            shadow_and_caution: "Fatigue from heavy operational volume, frustration with repetitive routines, and temporary slumps.".to_string(),
            tactical_remedy: "Discipline equals freedom; systematically complete checklists and harden foundational infrastructure.".to_string(),
        }),
        5 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Personal Year 5: Pivot & Breakthrough".to_string(),
            classical_grounding: "Epicycle Dynamics: 'Year 5 is the epicenter of the cycle; swept by winds of change, adventure, and boundary expansion.'".to_string(),
            modern_translation: "Business model pivots, opening international markets, dynamic course corrections, and adaptive agility.".to_string(),
            shadow_and_caution: "Panic over unexpected volatility, or succumbing to reckless dissipation and hazardous gambles.".to_string(),
            tactical_remedy: "Ride the waves of change with flexible agility, while keeping core capital reserves firmly fastened.".to_string(),
        }),
        6 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Personal Year 6: Duty, Community & Harmony".to_string(),
            classical_grounding: "Epicycle Dynamics: 'Year 6 ripens the orchard; dedicating stewardship to home, team, and harmonious restoration.'".to_string(),
            modern_translation: "Team building, workplace culture scaling, strengthening family bonds, and upgrading living environments.".to_string(),
            shadow_and_caution: "Emotional burnout from attempting to shoulder family and organizational burdens single-handedly.".to_string(),
            tactical_remedy: "Prioritize relational healing and internal cohesion with your closest circle of collaborators and family.".to_string(),
        }),
        7 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Personal Year 7: Reflection & Soul Awakening".to_string(),
            classical_grounding: "Epicycle Dynamics: 'Year 7 is the sacred sabbath; pause external expansion to deepen inner wisdom.'".to_string(),
            modern_translation: "Specialized skill acquisition, sabbatical/deep research, mental health renewal, and long-range strategic synthesis.".to_string(),
            shadow_and_caution: "Feelings of isolation, and frustration when attempting to force external commercial expansion during a rest year.".to_string(),
            tactical_remedy: "Refrain from premature aggressive expansion; invest deeply in research, writing, and systemic purification.".to_string(),
        }),
        8 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Personal Year 8: Material Harvest & Empowerment".to_string(),
            classical_grounding: "Epicycle Dynamics: 'Year 8 is the great harvest of seven years of toil; reaping authority, financial abundance, and sovereign power.'".to_string(),
            modern_translation: "Peak financial returns, executive authority acquisition, major liquidity exits, and maximum industry influence.".to_string(),
            shadow_and_caution: "Arrogance born of material triumph, and risking hard-won gains through reckless double-or-nothing bets.".to_string(),
            tactical_remedy: "Harvest yields into permanent defensive assets; preserve karmic balance through generosity and integrity.".to_string(),
        }),
        9 => Some(SymbolInterpretation {
            engine: "Pythagorean Numerology".to_string(),
            symbol: "Personal Year 9: Completion & Grand Transition".to_string(),
            classical_grounding: "Epicycle Dynamics: 'Year 9 is the grand finale of the cycle; shedding outworn skins to prepare space for renewal.'".to_string(),
            modern_translation: "Concluding long-term initiatives, terminating dead-end partnerships, and clearing the stage for the next 9-year cycle.".to_string(),
            shadow_and_caution: "Clinging to decaying relationships and lingering nostalgia; anxiety about the impending unknown.".to_string(),
            tactical_remedy: "Do not initiate brand-new multi-year projects; cleanly tie up loose ends and release with gratitude.".to_string(),
        }),
        _ => None,
    }
}
